                } else {
                    splits += 1
                    currentSum = num
                    if (splits > k) return false
                }
            }
            true
        }

        val maxNum = nums.max
        val sumNums = nums.sum
        var left = maxNum
        var right = sumNums

        while (left < right) {
            val mid = left + (right - left) / 2
